import json
def f(g):
    g=[r[:] for r in g]; H=len(g); W=len(g[0])
    seg=[(i,j,v) for i in range(H) for j in range(W) if g[i][j] and i==0]
    singles=[(i,j,v) for i in range(H) for j in range(W) if g[i][j] and i!=0]
    byv={}
    for _,c2,v2 in seg: byv.setdefault(v2,[]).append(c2)
    out=[r[:] for r in g]
    for v in set(seg):
        # vertical line down from each segment cell to bottom
        for c2 in byv.get(v,[]):
            for ii in range(H): out[ii][c2]=v
    for i,j,v in singles:
        # arm toward nearest segment cell with same color along row
        cands=[(abs(c-j),c) for _,c,w2 in seg if w2==v]
        if not cands: continue
        d,c=min(cands)
        step=1 if c>j else -1
        for jj in range(j+step, c+step, step): out[i][jj]=v
    return out

